A.ba1=new B.c(A.M,["Em um mundo que bombardeia nossa mente dizendo que s\xf3 seremos felizes se comprarmos mais, a B\xedblia ensina o segredo do contentamento.",A.aKN,"Rico n\xe3o \xe9 quem mais tem, mas quem menos precisa para ser plenamente grato e feliz no Senhor.","Descanse na provis\xe3o divina e receba o refrig\xe9rio do contentamento b\xedblico."],t.R)
A.bvc=new B.a7("tpl-32","A Verdadeira Riqueza do Contentamento","Vencendo a Ditadura do Consumismo e a Ansiedade Material","1 Tim\xf3teo 6:6-10; Filipenses 4:11-13","Tem\xe1tico",A.aOd,A.ba1)
